begin;
update gac_private.checkout_settings set enabled=true where singleton;
do $$declare o uuid;m uuid:=extensions.gen_random_uuid();g uuid:=extensions.gen_random_uuid();future_group uuid:=extensions.gen_random_uuid();meta jsonb;expiry timestamptz;oid uuid;req uuid:=extensions.gen_random_uuid();checkout uuid;
begin
 select user_id into strict o from gac_private.owners limit 1;
 select jsonb_build_object('full_name','Synthetic Selection Test','phone','5555550199','age_confirmed',true,'law_agreed',true,'accuracy_confirmed',true,'recognition_acknowledged',true,'requirements_version',version,'minimum_age',minimum_age,'callsign','PAUSE_'||left(replace(m::text,'-',''),12)) into meta from public.gac_requirements where singleton;
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)values(m,'selection-'||m||'@example.invalid',now(),meta);
 insert into public.gac_collections(id,callsign,quantity,price_cents,state,release_at,is_test)values(g,'SELECTION_ROLLBACK_FIXTURE',4,100,'open',now()-interval '1 minute',false),(future_group,'PRERELEASE_ROLLBACK_FIXTURE',4,100,'draft',now()+interval '1 day',false);
 perform set_config('request.jwt.claim.sub',m::text,true);set local role authenticated;
 begin perform public.gac_owner_set_selection_paused(g,true);raise exception 'Nonowner paused selection';exception when insufficient_privilege then null;end;
 perform public.gac_hold_number(g,2);reset role;
 perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;perform public.gac_hold_number(g,3);reset role;
 select expires_at into expiry from gac_private.number_holds where collection_id=g and edition_number=3;
 set local role authenticated;perform public.gac_owner_set_selection_paused(g,true);reset role;
 if not exists(select 1 from gac_private.number_holds where collection_id=g and edition_number=3 and expires_at=expiry) then raise exception 'Pause altered existing hold';end if;
 perform set_config('request.jwt.claim.sub',m::text,true);set local role authenticated;
 begin perform public.gac_hold_number(g,1);raise exception 'Paused selection accepted';exception when raise_exception then if sqlerrm<>'Number selection is temporarily paused' then raise;end if;end;
 perform public.gac_release_my_numbers(g,2);reset role;
 perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;
 checkout:=public.gac_begin_hosted_checkout(g,array[3],true,extensions.gen_random_uuid());
 oid:=public.gac_owner_assign_number(future_group,m,1,'complimentary','Before release','',req);
 if public.gac_owner_assign_number(future_group,m,1,'complimentary','Before release','',req)<>oid then raise exception 'Duplicate assignment retry';end if;
 begin perform public.gac_owner_assign_number(future_group,o,1,'complimentary','Overwrite','',extensions.gen_random_uuid());raise exception 'Assigned number overwritten';exception when raise_exception then if sqlerrm<>'This number is already assigned' then raise;end if;end;
 perform public.gac_owner_set_selection_paused(g,false);reset role;
 perform set_config('request.jwt.claim.sub',m::text,true);set local role authenticated;perform public.gac_hold_number(g,2);reset role;
 perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;perform public.gac_owner_set_selection_paused(g,true);
 begin perform public.gac_owner_assign_number(g,o,2,'complimentary','Held number','',extensions.gen_random_uuid());raise exception 'Other member hold overwritten';exception when raise_exception then if sqlerrm<>'This number is held by another member' then raise;end if;end;
 reset role;
 update public.gac_collections set state='open' where id=future_group;
 perform set_config('request.jwt.claim.sub',m::text,true);set local role authenticated;
 begin perform public.gac_hold_number(future_group,2);raise exception 'Member selected before release';exception when raise_exception then if sqlerrm<>'Collection is not open' then raise;end if;end;
 begin perform public.gac_owner_assign_number(future_group,m,2,'complimentary','Unauthorized','',extensions.gen_random_uuid());raise exception 'Member manually assigned';exception when insufficient_privilege then null;end;
 reset role;
 if not exists(select 1 from public.gac_orders where id=oid and user_id=m and assignment_kind='complimentary') then raise exception 'Pre-release receipt missing';end if;
 update public.gac_collections set state='closed' where id=g;
 perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;
 begin perform public.gac_owner_set_selection_paused(g,false);raise exception 'Closed collection resumed';exception when raise_exception then if sqlerrm<>'Choose a draft or open collection before recognition starts' then raise;end if;end;
 reset role;
end $$;
rollback;
